import React from "react";
import { motion } from "framer-motion";
import Typewriter from "typewriter-effect";
import { Heading, Text } from "@chakra-ui/react";
import { AppWrap } from "../../wrapper";
import "./Header.scss";

const Header = () => {
  return (
    <div className="app__header">
      <motion.div
        whileInView={{ x: [-70, 0], opacity: [0, 1] }}
        transition={{ duration: 1 }}
      >
        <Text fontSize={{ base: "2xl", sm: "3xl", md: "4xl" }}>
          Hello, my name is
        </Text>
        <Heading fontSize={{ base: "4xl", sm: "6xl", md: "75" }}>
          Zuhed Shaikh
        </Heading>
        <Heading
          fontSize={{ base: "lg", sm: "3xl", md: "4xl" }}
          color="#313BAC"
        >
          <Typewriter
            onInit={(typewriter) => {
              typewriter
                .changeDeleteSpeed(10)
                .pauseFor(500)
                .typeString("Full Stack Developer")
                .pauseFor(800)
                .deleteAll()
                .typeString("Mobile Developer")
                .pauseFor(800)
                .deleteAll()
                .pauseFor(800)
                .typeString("Problem Solver")
                .pauseFor(800)
                .deleteAll()
                .pauseFor(800)
                .typeString("Cinephile")
                .pauseFor(800)
                .deleteAll()
                .start();
            }}
            options={{
              loop: true,
            }}
          />
        </Heading>
      </motion.div>
    </div>
  );
};

export default AppWrap(Header, "home");
