import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { AiFillEye, AiFillGithub } from "react-icons/ai";
import { Box, HStack, Image, Text, Tooltip, useColorMode } from "@chakra-ui/react";
import { AppWrap } from "../../wrapper";
import { urlFor, client } from "../../client";
import "./Work.scss";

const filters = ["All", "HTML", "React", "MERN"];

const Work = () => {
  const [activeFilter, setActiveFilter] = useState("All");
  const [animateCard, setAnimateCard] = useState({ y: 0, opacity: 1 });
  const [works, setWorks] = useState([]);
  const [filterWork, setFilterWork] = useState([]);
  const [skills, setSkills] = useState([]);
  const { colorMode } = useColorMode();

  useEffect(() => {
    const query = '*[_type == "works"]';
    client.fetch(query).then((data) => {
      setWorks(data);
      setFilterWork(data.sort((a, b) => new Date(b._createdAt) - new Date(a._createdAt)));
    });

    const skills = '*[_type == "skills"]';
    client.fetch(skills).then((data) => {
      setSkills(data);
    });
  }, []);

  const handleWorkFilter = (item) => {
    setActiveFilter(item);
    setAnimateCard([{ y: 100, opacity: 0 }]);

    setTimeout(() => {
      setAnimateCard([{ y: 0, opacity: 1 }]);

      if (item === "All") {
        setFilterWork(works);
      } else {
        setFilterWork(works.filter((work) => work.tags?.includes(item)));
      }
    }, 500);
  };

  return (
    <div className="app__works">
      <h2 className="head-text">
        My Creative <span>Projects</span>
      </h2>

      <div className="app__work-filter">
        {filters.map((item, index) => (
          <div
            key={index}
            onClick={() => handleWorkFilter(item)}
            className={`app__work-filter-item app__flex p-text ${activeFilter === item ? "item-active" : ""} ${
              colorMode === "dark" ? "dark-mode-odd" : "light-mode"
            }`}
          >
            {item}
          </div>
        ))}
      </div>

      <motion.div
        animate={animateCard}
        transition={{ duration: 0.5, delayChildren: 0.5 }}
        className="app__work-portfolio"
      >
        {filterWork.map((work, index) => (
          <div
            key={index}
            className={`app__work-item app__flex ${colorMode === "dark" ? "dark-mode-card" : "light-mode"}`}
            onClick={(e) => e.preventDefault()}
          >
            <div className="app__work-img app__flex">
              <img src={urlFor(work.imgUrl)} alt={work.name} />
            </div>

            <div className="app__work-content app__flex">
              <h3 className="bold-text">{work.title}</h3>
              <p className="p-text" style={{ marginTop: 10 }}>
                {work.description}
              </p>
            </div>

            <Box my="3" w="full">
              <Text fontWeight="bold" textAlign="left" w="full">
                Tech Stack:
              </Text>
              <HStack className="app__work-techstack" justify="flex-start" w="full" align="center" flexWrap="wrap">
                {skills
                  .filter((skill) => work.tags?.includes(skill.name))
                  .map((skill, index) => (
                    <Tooltip key={index} fontSize={14} px={4} py={1} label={skill.name} hasArrow placement="top">
                      <Image className="app__work-item-tech" src={urlFor(skill.icon)} alt={skill.name} />
                    </Tooltip>
                  ))}
              </HStack>
            </Box>

            <HStack className="app__work-item-icons" justifyContent="space-between">
              <div title={work.projectLink} onClick={() => window.open(work.projectLink, "_blank")}>
                <AiFillEye />
              </div>
              <div title={work.codeLink} onClick={() => window.open(work.codeLink, "_blank")}>
                <AiFillGithub />
              </div>
            </HStack>
          </div>
        ))}
      </motion.div>
    </div>
  );
};

export default AppWrap(Work, "projects");
// export default Work;
