import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { AppWrap } from "../../wrapper";
import { urlFor, client } from "../../client";
import { useColorMode } from "@chakra-ui/react";
import "./Skills.scss";

const filters = ["All", "Frontend", "Backend"];

const Skills = () => {
  const [skills, setSkills] = useState([]);
  const [skillFilter, setSkillFilter] = useState([]);
  const [activeFilter, setActiveFilter] = useState("All");
  const { colorMode } = useColorMode();

  useEffect(() => {
    const query = '*[_type == "skills"]';

    client.fetch(query).then((data) => {
      setSkills(data);
      setSkillFilter(data);
    });
  }, []);

  const handleSkillFilter = (item) => {
    setActiveFilter(item);
    setSkillFilter(skills.filter((skill) => skill.tags.includes(item)));
  };

  return (
    <>
      <h2 className="head-text">
        My <span>Skills</span>
      </h2>

      <div className="app__skill-filter">
        {filters.map((item, index) => (
          <div
            key={index}
            onClick={() => handleSkillFilter(item)}
            className={`app__skill-filter-item app__flex p-text ${
              activeFilter === item ? "item-active" : ""
            } ${colorMode === "dark" ? "dark-mode-odd2" : "light-mode"}`}
          >
            {item}
          </div>
        ))}
      </div>

      <div className="app__skills-container">
        <motion.div className="app__skills-list">
          {skillFilter.map((skill, index) => (
            <motion.div
              key={index}
              whileInView={{ scale: [0, 1], opacity: [0, 1] }}
              transition={{ duration: 0.2 }}
              className={`app__skills-item app__flex`}
            >
              <a href={skill.link} target="_blank" rel="noopener noreferrer">
                <div
                  className={`app__flex`}
                  style={{
                    backgroundColor:
                      colorMode === "dark" ? "#0F1624" : "#EDF2F8",
                  }}
                >
                  <img src={urlFor(skill.icon)} alt={skill.name} />
                </div>
              </a>
              <p className="p-text">{skill.name}</p>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </>
  );
};

export default AppWrap(Skills, "skills", "app__skills app__whitebg");
