import { useEffect, useState } from "react";
import { FaSun } from "react-icons/fa";
import { RiMoonClearFill } from "react-icons/ri";
import { Heading, Container, Flex, Spacer, HStack, Button, useColorMode } from "@chakra-ui/react";
import "./Navbar.scss";

const navlinks = ["home", "about", "projects", "skills", "github", "contact"];

const Navbar = () => {
  const [active, setActive] = useState("home");
  const { colorMode, toggleColorMode } = useColorMode();

  useEffect(() => {
    window.addEventListener("scroll", (event) => {
      if (window.scrollY === 0) {
        setActive("home");
      } else if (window.scrollY >= 3400) {
        setActive("contact");
      } else {
        setActive(navlinks[Math.floor(window.scrollY / 1000) + 1]);
      }
    });
  }, []);

  return (
    <Container className={`app__navbar ${colorMode === "dark" ? "dark-mode" : "nav-light"}`} maxW="full">
      <Flex alignItems="center">
        <Heading fontSize={"3xl"}>
          ZU<span style={{ color: "#313bac" }}>HED</span>
        </Heading>

        <Spacer />

        <HStack className="app__navbar-links" display={{ base: "none", md: "inline-flex" }}>
          {navlinks.map((link, index) => (
            <a key={`link-${index}`} href={`#${link}`}>
              <Button
                variant="unstyled"
                className={`${active === link ? "active" : ""}`}
                onClick={() => setActive(link)}
              >
                {link}
              </Button>
            </a>
          ))}
          {/* <a
            href="https://drive.google.com/file/d/1Z01YkXK7b87bPwefyyuYmk8QkWUwR_QR/view"
            target="_blank"
            rel="noopener noreferrer"
          > */}
          <Button className="resume-btn" variant="ghost">
            Resume
          </Button>
          {/* </a> */}
        </HStack>

        <Button ml={{ base: 0, md: 6 }} onClick={toggleColorMode} bg="" _hover={{}}>
          {colorMode === "dark" ? <FaSun size={25} /> : <RiMoonClearFill size={25} />}
        </Button>
      </Flex>
    </Container>
  );
};

export default Navbar;
