import { Stack, Text, useColorMode } from '@chakra-ui/react';
import { useRecoilValue } from 'recoil';
import { visitState } from '../../atoms';
import './Footer.scss';

const Footer = () => {
  const visits = useRecoilValue(visitState);
  const { colorMode } = useColorMode();

  return (
        <Stack justify='center' align='center' direction='column' py='2' className={`${colorMode === 'dark' ? 'dark-mode' : ''}`}>
            <Text>Made with 💖 and ☕ by Zuhed Shaikh</Text>
            <Text display={{ base: 'block', sm: 'none' }}>
              Visitors:{" "}
              {visits.message === "Welcome!" ? (
                <span>{visits.count - 1} + <span style={{ color: 'green' }}>1</span></span>
              ) : (
                <span>{visits.count}</span>
              )}
            </Text>
        </Stack>
  )
}

export default Footer;