import {
  Button,
  ButtonGroup,
  Container,
  Grid,
  GridItem,
  HStack,
  Input,
  Stack,
  Text,
  Textarea,
  useColorMode,
  useToast,
} from "@chakra-ui/react";
import emailjs from "emailjs-com";
import { useState } from "react";
import { BsTwitter } from "react-icons/bs";
import { FaGithub, FaLinkedin } from "react-icons/fa";
import { IoLocationSharp, IoMail } from "react-icons/io5";
import { AppWrap } from "../../wrapper";
import "./Contact.scss";

const OAuthLinks = [
  {
    icon: <FaLinkedin />,
    bg: "#0A66C2",
    link: "https://www.linkedin.com/in/zuhedshaikh95/",
  },
  {
    icon: <FaGithub />,
    bg: "#24292F",
    link: "https://github.com/zuhedshaikh95/",
  },
  { icon: <BsTwitter />, bg: "#03a9f4", link: "https://twitter.com/" },
];

const Inputs = [
  { type: "text", placeholder: "Full name", name: "from_name" },
  { type: "email", placeholder: "Email", name: "reply_to" },
  { type: "tel", placeholder: "Phone", name: "mobile" },
];

const ContactInfo = [
  { body: "zuhed95@gmail.com", icon: <IoMail /> },
  { body: "Maharashtra, India", icon: <IoLocationSharp /> },
];

const initialState = {
  from_name: "",
  reply_to: "",
  message: "",
  mobile: "",
};

const emailRegex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
const mobileRegex = /^[0-9]{10}$/;
const nameRegex = /^[A-Za-z\s]+$/;

const Contact = () => {
  const toast = useToast();
  const [formInput, setFormInput] = useState(initialState);
  const { colorMode } = useColorMode();

  const handleFormChange = (event) => {
    const { name, value } = event.target;
    setFormInput({ ...formInput, [name]: value });
  };

  const callToast = (title, message, status, duration = 2000) => {
    toast({
      position: "top",
      title: title,
      description: message,
      status: status,
      duration: duration,
      isClosable: true,
    });
  };

  const handleMessage = (event) => {
    event.preventDefault();

    for (let key in formInput) {
      if (key === "from_name" && (!nameRegex.test(formInput[key]) || formInput[key].length < 3)) {
        return callToast("Error", "Please enter valid name!", "error");
      } else if (key === "reply_to" && !emailRegex.test(formInput[key])) {
        return callToast("Error", "Invalid email!", "error");
      } else if (key === "mobile" && !mobileRegex.test(formInput[key])) {
        return callToast("Error", "Invalid phone number!", "error");
      } else if (key === "message" && formInput[key].length < 3) {
        return callToast("Error", "Message is too short!", "error");
      }
    }

    callToast("Status", "Sending message!", "loading");

    emailjs.send("service_du8hhn3", "template_w9pbpg9", formInput, "bu-Mni7f0mSg64HWi").then(
      (result) => {
        callToast("Message sent!", "Thank you for your message!", "success");
        event.target.reset();
        setFormInput(initialState);
      },
      (error) => {
        callToast("Error", "Something went wrong!", "error");
        console.log(error);
      }
    );
  };

  return (
    <div className="app__contact">
      <h2 className="head-text">
        Let's <span>connect</span> and <span>grow</span>
      </h2>

      <Container
        bg="url('https://storage.googleapis.com/lumen5-site-images/website-assets/cta-bg.png')"
        borderRadius="20"
        maxW="full"
        py="10"
        px={{ base: "5", md: "20" }}
        my="10"
      >
        <Grid
          gridTemplateColumns={{ base: "repeat(1, 1fr)", md: "repeat(2, 1fr)" }}
          alignItems="center"
          justifyContent="center"
          m="auto"
          gap="20"
        >
          <GridItem>
            <Stack spacing={{ base: "5", md: "10" }} textAlign="right" w="max-content" m="auto">
              {ContactInfo.map(({ body, icon }, index) => (
                <HStack key={index} color="#fff" gap="">
                  <Text fontSize="25">{icon}</Text>
                  <Text color="#fff" fontWeight="medium">
                    {body}
                  </Text>
                </HStack>
              ))}
            </Stack>
          </GridItem>

          <GridItem>
            <ButtonGroup variant="outline" spacing="4" width="full">
              {OAuthLinks.map(({ icon, bg, link }, index) => (
                <a key={index} href={link} target="_blank" rel="noopener noreferrer" style={{ width: "100%" }}>
                  <Button
                    border="0"
                    key={index}
                    _hover={{ opacity: 0.8 }}
                    width="full"
                    bg={bg}
                    color="#fff"
                    fontSize="20"
                  >
                    {icon}
                  </Button>
                </a>
              ))}
            </ButtonGroup>
            <form onSubmit={handleMessage}>
              <Stack mt="8" w="full" spacing="5">
                {Inputs.map(({ type, placeholder, name }, index) => (
                  <Input
                    key={index}
                    type={type}
                    placeholder={placeholder}
                    bg="#fff"
                    name={name}
                    onChange={handleFormChange}
                    color={colorMode === "dark" ? "black" : ""}
                    _placeholder={{ color: colorMode === "dark" ? "gray" : "" }}
                  />
                ))}
                <Textarea
                  placeholder="Your message"
                  bg="#fff"
                  resize="none"
                  h="150"
                  name="message"
                  onChange={handleFormChange}
                  _placeholder={{ color: colorMode === "dark" ? "gray" : "" }}
                ></Textarea>
                <Button
                  type="submit"
                  bg="var(--secondary-color)"
                  value="Send Message"
                  color="#fff"
                  border="0"
                  cursor="pointer"
                  _hover={{}}
                >
                  Send Message
                </Button>
              </Stack>
            </form>
          </GridItem>
        </Grid>
      </Container>
    </div>
  );
};

export default AppWrap(Contact, "contact");
