import { Text, useColorMode } from "@chakra-ui/react";
import { useEffect, useState } from "react";
import { useRecoilState } from "recoil";
import { visitState } from "../../atoms";
import { Loader } from "..";
import './Visitors.scss';

const Visitors = () => {
    const [loading, setLoading] = useState(true);
    const [visits, setVisits] = useRecoilState(visitState);
    const { colorMode } = useColorMode();

    useEffect(() => {
        (async () => {
        setLoading(true);
        try {
            const data = await fetch("https://portfolio-analytics.onrender.com/visit").then((res) => res.json());
            setVisits(data);
        } catch ({ response }) {
            console.log(response);
        } finally {
            setLoading(false);
        }
        })();
    }, [setVisits]);

  return (
    <div className="app__visitors">
        {loading ? (
          <Loader size={35} />
        ) : (
          visits.count && (
            <Text className="app__social-visit-text" color={`${colorMode === 'dark' ? 'white' : ''}`}>
              Visitors:{" "}
              {visits.message === "Welcome!" ? (
                <span>
                  {visits.count - 1} + <span style={{ color: "green" }}>1</span>
                </span>
              ) : (
                <span>{visits.count}</span>
              )}
            </Text>
          )
        )}
    </div>
  )
}

export default Visitors