import { Flex, Image, useColorMode } from "@chakra-ui/react";
import GitHubCalendar from "react-github-calendar";
import ReactTooltip from "react-tooltip";
import { AppWrap } from "../../wrapper";
import { stats } from '../../constants';
import "./Calendar.scss";

const Calendar = () => {
  const { colorMode } = useColorMode();

  return (
    <div className="app__calendar">
      <h2 className="head-text" style={{ marginBottom: "4rem" }}>
        GitHub <span>Contributions</span>
      </h2>
      <GitHubCalendar
        className="app__github-calendar"
        username="zuhedshaikh95"
        year="last"
        showWeekdayLabels
        style={{ width: "100%", margin: "0 auto 3rem auto" }}
        fontSize={16}
      >
        <ReactTooltip html />
      </GitHubCalendar>

      <h2 className="head-text">
        Github <span>Stats</span>
      </h2>
      <Flex
        justify="center"
        direction={{ base: "column", md: "row" }}
        maxW="max-content"
        flexWrap="wrap"
        m="auto"
        gap="5"
        py="5"
      >
        {stats.map((stat, index) => (
          <Image
            key={index}
            src={colorMode === "dark" ? stat.linkDark : stat.linkLight}
            alt={stat.title}
          />
        ))}
      </Flex>
    </div>
  );
};

export default AppWrap(Calendar, "github", "app__whitebg");
