import { Link } from "@chakra-ui/react";
import { BsGithub, BsLinkedin } from "react-icons/bs";

const SocialMedia = () => {
  return (
    <div className="app__social">
      <div className="app__social-icon-link">
        <Link href="https://www.github.com/zuhedshaikh95" isExternal>
          <BsGithub />
        </Link>
      </div>
      <div className="app__social-icon-link">
        <Link href="https://www.linkedin.com/in/zuhedshaikh95/" isExternal>
          <BsLinkedin />
        </Link>
      </div>
    </div>
  );
};

export default SocialMedia;
